const KEY='high-low:v1';
const nonnegative=v=>Number.isFinite(v)&&v>=0?v:0;
export function load(storage){try{storage??=globalThis.localStorage;const d=JSON.parse(storage.getItem(KEY));if(d?.version===1&&d.records&&typeof d.records==='object'&&!Array.isArray(d.records)){const records={};for(const key of ['EASY','NORMAL','HARD']){const r=d.records[key];if(r&&typeof r==='object')records[key]={best:nonnegative(r.best),plays:Math.floor(nonnegative(r.plays)),maxCombo:Math.floor(nonnegative(r.maxCombo)),lastPlayed:typeof r.lastPlayed==='string'?r.lastPlayed:null}}return {version:1,records}}}catch{}return {version:1,records:{}}}
export function record(difficulty,game,storage){const data=load(storage),old=data.records[difficulty]||{};const best=old.best||0;const isBest=game.score>best;data.records[difficulty]={best:Math.max(best,game.score),plays:(old.plays||0)+1,maxCombo:Math.max(old.maxCombo||0,game.maxCombo),lastPlayed:new Date().toISOString()};try{storage??=globalThis.localStorage;storage.setItem(KEY,JSON.stringify(data));return {isBest,saved:true}}catch{return {isBest,saved:false}}}
